    _pool.push({
      active: false,
      x: 0,
      y: 0,
      vx: 0,
      vy: 0,
      life: 0,
      maxLife: 0,
      radius: 0,
      color: '#ffffff',
      type: 'explosion'
    });
  }

  function _getInactive() {
    for (let i = 0; i < POOL_SIZE; i++) {
      if (_pool[i].active === false) {
        return _pool[i];
      }
    }
