  function init() {
    _canvas = document.getElementById('game-canvas');
    _ctx    = _canvas.getContext('2d');

    const stored = localStorage.getItem('spaceGameHighscore');
    _state.highscore = stored !== null ? Number(stored) : 0;

    _resetState();

    // Bug 1 fix: init() accepts no parameters
    SPACE_GAME.Obstacles.init();
    SPACE_GAME.Particles.reset();
    // Bug 5 fix: use SPACE_GAME.HUD (all caps)
    SPACE_GAME.HUD.init();
    SPACE_GAME.Audio.init();
    SPACE_GAME.Controls.setPauseCallback(_togglePause);

    if (!_listenersAttached) {
      _listenersAttached = true;

      document.getElementById('btn-start').addEventListener('click', function () {
        document.getElementById('screen-menu').classList.add('hidden');
        document.getElementById('screen-game').classList.remove('hidden');
        SPACE_GAME.Controls.activate();
        SPACE_GAME.Game.start();
      });

      document.getElementById('btn-restart').addEventListener('click', function () {
        document.getElementById('screen-gameover').classList.add('hidden');

        // Clean up level classes
        document.body.classList.remove('is-level-1', 'is-level-2', 'is-level-3');
        document.body.classList.add('is-level-1');

        // Clean up state classes
        const screenGame = document.getElementById('screen-game');
        screenGame.classList.remove('is-paused', 'is-damaged', 'is-boosted', 'is-shielded');

        // Bug 1 fix: init() accepts no parameters
        SPACE_GAME.Obstacles.init();
        SPACE_GAME.Particles.reset();
        // Bug 5 fix: use SPACE_GAME.HUD (all caps)
        SPACE_GAME.HUD.reset();

        _state.highscore = Number(localStorage.getItem('spaceGameHighscore')) || 0;
        _resetState();

        SPACE_GAME.Controls.activate();
        document.getElementById('screen-game').classList.remove('hidden');
        SPACE_GAME.Game.start();
      });

      document.getElementById('btn-resume').addEventListener('click', function () {
        SPACE_GAME.Game.resume();
      });
    }

    document.body.classList.remove('is-level-1', 'is-level-2', 'is-level-3');
    document.body.classList.add('is-level-1');
  }

  // ─── Public: start ───────────────────────────────────────────────────────────
  function start() {
    _state.lastTime = performance.now();
    _state.rafId    = requestAnimationFrame(_loop);
  }

  // ─── Public: stop (game over) ────────────────────────────────────────────────
  function stop() {
    cancelAnimationFrame(_state.rafId);
    _state.isGameOver = true;

    SPACE_GAME.Controls.deactivate();

    // Update highscore
    if (_state.score > _state.highscore) {
      _state.highscore = _state.score;
      localStorage.setItem('spaceGameHighscore', String(_state.highscore));
    }

    // Clean up state classes
    const screenGame = document.getElementById('screen-game');
    screenGame.classList.remove('is-paused', 'is-boosted', 'is-shielded');

    screenGame.classList.add('hidden');

    document.getElementById('gameover-score').textContent     = _state.score;
    document.getElementById('gameover-highscore').textContent = _state.highscore;
    document.getElementById('screen-gameover').classList.remove('hidden');
  }

  // ─── Public: pause ───────────────────────────────────────────────────────────
  function pause() {
    if (_state.isGameOver || _state.isPaused) return;
    _state.isPaused = true;
    document.getElementById('overlay-pause').classList.remove('hidden');
    document.getElementById('screen-game').classList.add('is-paused');
  }

  // ─── Public: resume ──────────────────────────────────────────────────────────
  function resume() {
    if (!_state.isPaused) return;
    _state.isPaused = false;
    // Reset lastTime so dt doesn't spike after unpause
    _state.lastTime = performance.now();
    document.getElementById('overlay-pause').classList.add('hidden');
    document.getElementById('screen-game').classList.remove('is-paused');
  }

  // ─── Public: getState ────────────────────────────────────────────────────────
  function getState() {
    return _state;
  }

  // ─── Expose public API ───────────────────────────────────────────────────────
  window.SPACE_GAME.Game = {
    init:     init,
    start:    start,
    stop:     stop,
    pause:    pause,
    resume:   resume,
    getState: getState
  };

})();

* {
  box-sizing: border-box;
}

*::before,
*::after {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  padding: 0;
}

:root {
  --color-bg: #000011;
  --color-primary: #00ffff;
  --color-secondary: #ff00ff;
  --color-accent: #ffff00;
  --color-danger: #ff4444;
  --color-success: #44ff44;
  --color-text: #ffffff;
  --font-arcade: 'Courier New', 'Lucida Console', monospace;
  --canvas-width: 800px;
  --canvas-height: 600px;
  --z-canvas: 1;
  --z-hud: 10;
  --z-overlay: 20;
  --z-screen: 30;
  --z-modal: 40;
}

.hidden {
  display: none !important;
}

body {
  background-color: var(--color-bg);
  color: var(--color-text);
  font-family: var(--font-arcade);
  overflow: hidden;
  width: 100vw;
  height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
}

#game-canvas {
  display: block;
  width: var(--canvas-width);
  height: var(--canvas-height);
  position: relative;
  z-index: var(--z-canvas);
  border: 1px solid var(--color-primary);
  box-shadow: 0 0 20px var(--color-primary), 0 0 40px var(--color-primary);
}

.screen {
  position: absolute;
  top: 0;
  left: 0;
  width: var(--canvas-width);
  height: var(--canvas-height);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 24px;
  z-index: var(--z-screen);
  background-color: rgba(0, 0, 17, 0.92);
}

#screen-levelup {
  background-color: transparent;
  pointer-events: none;
}

#screen-game {
  position: absolute;
  top: 0;
  left: 0;
  width: var(--canvas-width);
  height: var(--canvas-height);
  z-index: var(--z-hud);
  background: transparent;
  pointer-events: none;
}

.neon-text {
  color: var(--color-primary);
  text-shadow:
    0 0 7px var(--color-primary),
    0 0 14px var(--color-primary),
    0 0 28px var(--color-primary);
  letter-spacing: 2px;
  text-transform: uppercase;
}

#menu-title {
  font-size: 2rem;
  color: var(--color-accent);
  text-shadow:
    0 0 7px var(--color-accent),
    0 0 14px var(--color-accent),
    0 0 28px var(--color-accent);
  letter-spacing: 2px;
  text-transform: uppercase;
  margin-bottom: 16px;
}

.btn-arcade {
  display: inline-block;
  padding: 12px 24px;
  background-color: transparent;
  border: 2px solid var(--color-primary);
  color: var(--color-primary);
  font-family: var(--font-arcade);
  font-size: 0.75rem;
  letter-spacing: 2px;
  text-transform: uppercase;
  cursor: pointer;
  transition: background-color 0.15s ease, color 0.15s ease, box-shadow 0.15s ease;
}

.btn-arcade:hover {
  background-color: var(--color-primary);
  color: var(--color-bg);
  box-shadow: 0 0 12px var(--color-primary);
}

.btn-arcade:active {
  transform: scale(0.97);
}

#hud-score {
  position: absolute;
  top: 12px;
  left: 16px;
  font-size: 0.65rem;
  color: var(--color-text);
}

#hud-level {
  position: absolute;
  top: 12px;
  right: 16px;
  font-size: 0.65rem;
  color: var(--color-accent);
}

#hud-lives {
  position: absolute;
  top: 32px;
  left: 16px;
  font-size: 0.65rem;
  color: var(--color-danger);
  display: flex;
  gap: 6px;
}

#hud-speed-bar {
  position: absolute;
  bottom: 16px;
  left: 16px;
  width: 120px;
  height: 8px;
  background-color: rgba(255, 255, 255, 0.15);
  border: 1px solid var(--color-primary);
  border-radius: 4px;
  overflow: hidden;
}

.speed-fill {
  height: 100%;
  width: 0%;
  background-color: var(--color-primary);
  transition: width 0.1s linear;
  border-radius: 4px;
}

#hud-powerup-alert {
  position: absolute;
  bottom: 40px;
  left: 50%;
  transform: translateX(-50%);
  background-color: rgba(0, 0, 17, 0.85);
  border: 1px solid var(--color-accent);
  padding: 6px 14px;
  font-size: 0.55rem;
  color: var(--color-accent);
  text-align: center;
  white-space: nowrap;
}

#overlay-pause {
  position: absolute;
  top: 0;
  left: 0;
  width: var(--canvas-width);
  height: var(--canvas-height);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 24px;
  z-index: var(--z-overlay);
  background-color: rgba(0, 0, 17, 0.75);
}

.scanline {
  position: absolute;
  top: 0;
  left: 0;
  width: var(--canvas-width);
  height: var(--canvas-height);
  background: repeating-linear-gradient(
    to bottom,
    transparent 0px,
    transparent 2px,
    rgba(0, 0, 0, 0.18) 2px,
    rgba(0, 0, 0, 0.18) 4px
  );
  pointer-events: none;
  z-index: var(--z-modal);
}

#star-field {
  position: absolute;
  top: 0;
  left: 0;
  width: var(--canvas-width);
  height: var(--canvas-height);
  pointer-events: none;
  z-index: 0;
}

.star-bg {
  position: absolute;
  border-radius: 50%;
  background-color: var(--color-text);
}

.powerup-icon {
  font-size: 0.6rem;
  color: var(--color-success);
}

.is-damaged #game-canvas {
  animation: damage-flash 0.5s steps(2, end);
}

@keyframes damage-flash {
  0%   { border-color: var(--color-danger); box-shadow: 0 0 20px var(--color-danger), 0 0 40px var(--color-danger); }
  50%  { border-color: var(--color-primary); box-shadow: 0 0 20px var(--color-primary), 0 0 40px var(--color-primary); }
  100% { border-color: var(--color-primary); box-shadow: 0 0 20px var(--color-primary), 0 0 40px var(--color-primary); }
}

.is-boosted #hud-speed-bar {
  border-color: var(--color-accent);
}

.is-boosted .speed-fill {
  background-color: var(--color-accent);
}

.is-shielded #game-canvas {
  box-shadow: 0 0 20px var(--color-success), 0 0 40px var(--color-success);
  border-color: var(--color-success);
}

.is-paused #game-canvas {
  opacity: 0.6;
}

body.is-level-1 {
  --color-primary: #00ffff;
}

body.is-level-2 {
  --color-primary: #ff00ff;
}

body.is-level-3 {
  --color-primary: #ffff00;
}

/* =============================================================
   css/responsive.css
   RESPONSIVE OVERRIDES ONLY — base styles live in css/styles.css
   This file ONLY contains media query overrides.
   Breakpoint order: desktop-first (largest → smallest)
   DO NOT redeclare :root variables outside @media blocks.
   DO NOT use @import. Loaded via <link> in index.html.
   ============================================================= */

/* ─────────────────────────────────────────────
   BREAKPOINT: TABLET — max-width: 900px
   ───────────────────────────────────────────── */
@media (max-width: 900px) {

  :root {
    --canvas-width: 90vw;
    --canvas-height: 67.5vw; /* mantiene ratio 4:3 (800×600) */
  }

  #game-canvas {
    width: var(--canvas-width);
    height: var(--canvas-height);
    max-width: 800px;
    max-height: 600px;
  }

  .screen {
    padding: 1rem;
  }

  .neon-text {
    font-size: 1rem;
  }

  #menu-title {
    font-size: 1.2rem;
  }

  .btn-arcade {
    font-size: 0.7rem;
    padding: 0.6rem 1.2rem;
  }

  #hud-score,
  #hud-level,
  #hud-lives {
    font-size: 0.55rem;
  }

  #hud-speed-bar {
    width: 80px;
  }

  #hud-powerup-alert {
    font-size: 0.55rem;
  }
}

/* ─────────────────────────────────────────────
   BREAKPOINT: MÓVIL — max-width: 600px
   ───────────────────────────────────────────── */
@media (max-width: 600px) {

  :root {
    --canvas-width: 100vw;
    --canvas-height: 75vw; /* mantiene ratio 4:3 a ancho completo */
  }

  #game-canvas {
    width: var(--canvas-width);
    height: var(--canvas-height);
    border-radius: 0;
  }

  .screen {
    padding: 0.5rem;
  }

  .neon-text {
    font-size: 0.7rem;
  }

  #menu-title {
    font-size: 0.9rem;
  }

  .btn-arcade {
    font-size: 0.6rem;
    padding: 0.5rem 0.8rem;
    width: 80%;
  }

  #hud-score,
  #hud-level,
  #hud-lives {
    font-size: 0.45rem;
  }

  #hud-speed-bar {
    width: 50px;
  }

  #hud-powerup-alert {
    font-size: 0.45rem;
    max-width: 90vw;
  }

  #overlay-pause {
    font-size: 0.8rem;
  }

  /* Garantiza cobertura total en móvil.
     NOTA AL TECH LEAD: si styles.css declara width/height fijos
     en px para .scanline o #star-field, estos overrides los corrigen.
     Verificar que styles.css no use valores fijos en esos selectores. */
  .scanline {
    width: 100%;
    height: 100%;
  }

  #star-field {
    width: 100%;
    height: 100%;
  }
}

/* ─────────────────────────────────────────────
   BREAKPOINT: ALTURA REDUCIDA — max-height: 500px
   Cubre landscape en móvil donde la altura es el recurso escaso.
   ───────────────────────────────────────────── */
@media (max-height: 500px) {

  :root {
    --canvas-height: 90vh;
    --canvas-width: 120vh; /* mantiene ratio 4:3 en orientación landscape */
  }

  #game-canvas {
    width: var(--canvas-width);
    height: var(--canvas-height);
    max-width: 100vw;
  }

  .screen {
    overflow-y: auto;
  }

  #menu-title {
    margin-bottom: 0.5rem;
  }

  .btn-arcade {
    margin: 0.3rem 0;
  }
}
